items.outputText:
{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회 쿼리의 병목에 맞는 개선 방법을 선택할 수 있는지 검증한다. 질문의 초점은 쿼리 개선 방법을 선택한 판단 근거이다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "운영 화면의 신고 목록 조회가 지연되던 당시의 쿼리 실행 상황이다.",
          "task": "조회 지연을 일으키는 병목에 적합한 개선 방법을 선택해야 하는 상황이다.",
          "action": "실행 계획 등에서 확인한 병목을 근거로 선택한 개선 방법이 적합하다고 판단한 이유를 설명한다.",
          "result": "선택한 방법이 해당 병목을 줄이는 데 기여한 내용을 설명한다. 별도의 개선 전후 측정 절차까지 설명할 필요는 없다."
        },
        "expectedEvidence": [
          "쿼리 개선 방법을 선택한 구체적인 판단 근거",
          "그 판단을 뒷받침하는 실행 계획, 로그 또는 호출 구조의 관찰 내용",
          "관찰한 병목과 선택한 개선 방법 사이의 인과관계"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회를 3.2초에서 0.4초로 줄이셨던데요, 당시 쿼리 개선 방법을 선택한 판단 근거는 뭐였어요?",
      "answerTip": "당시 장면을 떠올리며 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "선택한 개선 방법의 판단 근거를 당시 쿼리의 구체적인 특성으로 설명한다.",
            "실행 계획 등에서 관찰한 내용과 실제 병목을 연결한다.",
            "선택한 방법이 해당 병목을 줄이는 이유를 기술적으로 타당하게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "선택한 개선 방법과 병목에 대한 기본적인 판단 근거를 제시한다.",
            "다만 관찰한 실행 정보가 모호하거나, 해당 방법이 병목을 줄이는 이유에 대한 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "개선 방법이나 성능 수치만 나열하고 선택의 판단 근거를 제시하지 못한다.",
            "설명한 병목과 선택한 방법 사이에 관련성이 없거나 기술적인 설명이 타당하지 않다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "운영 오류의 원인에 맞는 수정 조치를 선택할 수 있는지 검증한다. 질문의 초점은 스케줄러 중복 실행에 대해 잠금 키 방식을 선택한 판단 근거이다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "배포 후 같은 알림이 두 번 발송되고 서버 두 대에서 스케줄러가 동시에 실행되던 상황이다.",
          "task": "확인한 중복 실행 원인에 적합한 수정 방식을 선택해야 하는 상황이다.",
          "action": "로그에서 확인한 실행 양상을 근거로 잠금 키 방식이 적합하다고 판단한 이유를 설명한다.",
          "result": "선택한 방식이 중복 실행을 막는 데 기여한 내용 또는 의도한 작동 효과를 설명한다. 별도의 배포 체크리스트나 재발 방지 계획 수립은 필수로 요구하지 않는다."
        },
        "expectedEvidence": [
          "잠금 키 방식을 선택한 구체적인 판단 근거",
          "서버 두 대의 스케줄러 동시 실행이라는 판단을 뒷받침한 로그 관찰 내용",
          "잠금 키가 확인된 중복 실행 원인을 억제하는 방식에 대한 설명"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송 오류를 수정하셨던데요, 스케줄러에 잠금 키를 두는 방식을 선택한 판단 근거는 뭐였어요?",
      "answerTip": "당시 장면을 떠올리며 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "잠금 키 방식의 선택 근거를 서버 두 대의 스케줄러 동시 실행과 구체적으로 연결한다.",
            "그 판단을 뒷받침한 로그의 실행 양상을 설명한다.",
            "선택한 잠금 방식이 서버 간 중복 실행을 막는 이유를 타당하게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "스케줄러 동시 실행을 막기 위해 잠금 키 방식을 선택했다는 기본적인 근거를 제시한다.",
            "다만 근거가 된 로그 관찰 내용이나 잠금 방식의 작동 효과에 대한 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "잠금 키를 적용했다는 사실만 말하고 선택한 판단 근거를 제시하지 못한다.",
            "로그로 확인한 원인과 수정 방식의 관련성을 설명하지 못하거나, 제시한 방식으로 중복 실행이 억제되는 이유가 타당하지 않다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "사용자 요청을 구현 가능한 요구사항으로 구체화할 때, 구현 범위에 포함할 기능을 구분한 판단 기준의 타당성을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "사용자 요청을 정리하며 개발 담당 팀원과 구현 범위를 조정해야 했던 상황이다.",
          "task": "서비스의 목적에 맞춰 구현 범위에 포함할 기능을 구분해야 했다.",
          "action": "요청의 목적과 구현 조건을 근거로 기능을 포함할 기준을 세우고 실제 요구사항에 적용한 내용을 설명한다.",
          "result": "해당 기준에 따라 포함하거나 제외하기로 정리한 기능이 드러난다. 이후 구현 성과까지 제시할 필요는 없다."
        },
        "expectedEvidence": [
          "구현 범위에 넣을 기능을 구분할 때 실제로 사용한 기준",
          "해당 기준이 사용자 요청의 목적이나 당시 구현 조건에 적합했던 이유",
          "기준을 적용해 포함 또는 제외하기로 정리한 구체적인 기능 사례"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 개발 담당 팀원과 범위를 조정하셨는데요, 구현 범위에 넣을 기능을 고른 기준은 뭐였어요?",
      "answerTip": "기억에 남는 한 장면을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "구현 범위를 구분한 기준을 구체적으로 설명하고, 사용자 요청의 목적이나 구현 조건에 비추어 그 기준이 적합했던 이유를 제시한다.",
            "실제 기능의 포함 또는 제외 결정으로 기준이 어떻게 적용되었는지 명확히 보여 준다."
          ]
        },
        "acceptable": {
          "criteria": [
            "구현 범위를 구분한 기준은 확인되지만, 해당 기준을 선택한 이유나 적용한 기능 사례가 충분히 구체적이지 않다.",
            "설명한 기준과 범위 결정 사이의 연결은 일부 확인된다."
          ]
        },
        "poor": {
          "criteria": [
            "구현 범위를 구분한 기준을 제시하지 않거나, 요청 목록과 문서 작성 사실만 설명한다.",
            "기준이 당시 요청이나 구현 조건과 어떻게 관련되는지 확인하기 어렵고, 실제 범위 결정의 근거도 드러나지 않는다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "화면설계서에 예외 상황을 표현할 때, 구현 담당자가 화면의 동작을 해석할 수 있을 만큼 구체적으로 명세했는지 확인한다. 초점은 예외 상황 하나를 화면에 표현한 내용이다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "예약 서비스의 화면설계서를 작성하면서 정상 흐름과 다른 예외 상황을 화면에 표현해야 했던 상황이다.",
          "task": "선택한 예외 상황에서 화면이 어떻게 보여야 하는지 구현 담당자가 이해할 수 있도록 명세해야 했다.",
          "action": "해당 예외가 발생하는 조건과 그때의 화면 상태, 사용자 안내 등 실제 화면설계서에 표현한 내용을 설명한다.",
          "result": "선택한 예외 상황에서 구현할 화면의 모습과 동작이 구체적으로 드러난다. 실제 개발 완료나 문의 감소는 필수 근거가 아니다."
        },
        "expectedEvidence": [
          "예외 상황 하나를 화면설계서에 실제로 표현한 내용",
          "그 표현이 적용되는 예외 발생 조건",
          "해당 상황의 화면 상태나 안내 문구 등 구현 내용을 명확하게 만드는 명세"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 화면설계서 28장을 작성하셨는데요, 예외 상황 하나는 화면에 어떤 내용으로 표현하셨어요?",
      "answerTip": "당시 작성한 내용을 떠올리며 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "예외 상황 하나를 특정하고, 그 상황이 발생하는 조건에 맞춰 화면설계서에 표현한 내용을 구체적으로 설명한다.",
            "화면 상태나 안내 문구 등의 명세를 통해 구현 담당자가 해당 상황의 화면과 동작을 명확히 이해할 수 있다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황 하나와 화면에 표현한 내용은 확인되지만, 발생 조건이나 화면 명세의 일부가 모호하다.",
            "예외 상황에서 화면이 어떻게 달라지는지는 대략 이해되나 구현 시 추가 확인이 필요한 부분이 남는다."
          ]
        },
        "poor": {
          "criteria": [
            "예외 상황을 포함했다는 사실만 말하고, 실제 화면설계서에 표현한 내용을 설명하지 않는다.",
            "예외 발생 조건과 화면 표현의 연결이 불분명하여 해당 상황에서 구현할 화면이나 동작을 파악하기 어렵다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "의심스러운 처방을 그대로 수행하지 않고 확인 전 투약을 보류할 수 있는지 검증한다. 진통제 용량이 평소와 달랐던 상황에서 투약을 멈춘 판단 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 들어온 상황이다.",
          "task": "처방의 정확성이 의심되는 상태에서 투약을 진행해도 되는지 판단해야 했다.",
          "action": "처방 용량의 차이를 어떤 정보에 비추어 의심했는지 설명하고, 확인 없이 투약하지 않기로 한 근거를 제시한다.",
          "result": "해당 판단에 따라 확인 전 투약이 보류되었음을 설명한다. 입력 오류 확인은 판단을 뒷받침하는 결과로 활용할 수 있으나 후속 처리 전체를 설명할 필요는 없다."
        },
        "expectedEvidence": [
          "진통제 투약을 멈추기로 한 구체적인 판단 근거",
          "평소 용량과 해당 처방 용량의 차이를 인식한 사실",
          "용량 차이를 곧바로 오류로 확정하지 않고 확인이 필요한 상태로 판단한 설명",
          "처방의 정확성을 확인하기 전에는 투약하지 않았다는 행동"
        ]
      },
      "question": "푸른결종합병원에서 수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 들어온 적이 있다고 하셨는데요, 당시 투약을 멈추기로 한 판단 근거는 무엇이었어요?",
      "answerTip": "당시 장면을 떠올리며 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "처방 용량의 차이를 어떤 정보에 비추어 의심했는지 구체적으로 설명한다.",
            "평소와 다르다는 이유만으로 오류를 단정하지 않고, 정확성을 확인해야 하므로 투약을 보류했다는 판단이 명확하다.",
            "실제로 확인 전 투약을 멈춘 행동이 판단 근거와 일관되게 연결된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소 용량과 달라 확인이 필요하다고 판단했고 투약을 멈췄다는 핵심 근거가 확인된다.",
            "다만 용량을 비교한 정보나 확인 전 투약을 보류한 이유가 개략적으로 제시된다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈춘 이유를 설명하지 못하거나 입력 오류였다는 사후 결과만 제시한다.",
            "처방이 의심스러워도 그대로 투약한다는 설명 등 확인 전 보류 원칙과 어긋나는 판단을 제시한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자 상태와 관련된 정보를 다음 근무자에게 빠짐없이 전달할 수 있는지 검증한다. 인수인계 체크리스트에 진통제 투여 시각을 포함한 판단 근거를 통해 교대 시 전달할 정보의 중요성을 판단하는 데 초점을 둔다.",
